                <tbody>
                  {requirements.map((req) => (
                    <tr
                      key={req.id}
                      role="link"
                      tabIndex={0}
                      onClick={() => router.push(`/requirements/${req.id}`)}
                      onKeyDown={(e) => {
                        if (e.key === "Enter" || e.key === " ") {
                          e.preventDefault();
                          router.push(`/requirements/${req.id}`);
                        }
